flow.typescript:
// D30 · Part 0~5 · 오늘의 흐름 전체: 전화 수신 → 방 → 비서(도구) → Handoff → 통화 기록 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_flow.ts
//   전화 한 통이 Trunk 검사를 통과해 방에 들어오고, 예약 담당이 도구로 빈자리를 확인한 뒤 수납 담당에게 넘기는 리허설
//   (대체: 실제 SIP·LLM 대신 규칙과 가짜 도구 · 번호와 주소는 예시값)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const NUMBERS = new Set(["+827012345678"]);
const IPS = new Set(["203.0.113.10"]);
const BOOKED = new Set(["10:00"]);

interface Entry {
  who: string;
  what: string;
  tool: string | null;
  agent: string;
}

const callLog: Entry[] = []; // 통화 기록: 누가 · 무엇을 · 어떤 도구로 · 담당

function log(who: string, what: string, tool: string | null = null, agent: string = "reservation"): void {
  callLog.push({ who, what, tool, agent });
}

function incoming(to: string, caller: string, ip: string): string | null {
  // Trunk 검사 + Dispatch Rule → 방 이름 (실패하면 null)
  return NUMBERS.has(to) && IPS.has(ip) ? "call-" + caller : null;
}

const room = incoming("+827012345678", "+821011112222", "203.0.113.10");
const userdata: { slot?: string | null } = {};
if (room) {
  log("phone", "전화 수신 (8 kHz)");
  userdata.slot = BOOKED.has("15:00") ? null : "15:00"; // 도구 check_slot
  log("assistant", `15시 빈자리 확인: ${userdata.slot !== null}`, "check_slot");
  log("assistant", `${userdata.slot} 예약 건 비용 5만 원`, null, "billing"); // '비용'이 나오면 Handoff
}
console.log(JSON.stringify(callLog, null, 1).slice(0, 400), "...");
check(room === "call-+821011112222" && callLog.map((e) => e.tool).join() === ",check_slot," && callLog[callLog.length - 1].agent === "billing" && incoming("+827000000000", "+8210", "203.0.113.10") === null, "방 입장 → 도구 사용 → 수납 담당 순서로 기록되고, 모르는 번호는 거절돼야 해요.");

tools.typescript:
// D30 · Part 1 · 도구 호출 한 바퀴: 사용자 말 → LLM의 도구 요청 → 실행 → 결과 → 답 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_tools.ts
//   functionTool로 등록한 함수를 LLM이 이름과 인자로 요청하면, 세션이 대신 실행하고 결과를 다시 LLM에게 돌려준다
//   (대체: @livekit/agents의 llm.tool·RunContext와 실제 LLM 대신, 규칙으로 도구를 요청하는 가짜 LLM)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface RunContext {
  userdata: { booked: string[] }; // 통화 전체가 공유하는 메모
}

type Tool = (ctx: RunContext, args: Record<string, string>) => Record<string, unknown>;
const TOOLS: Record<string, Tool> = {};

function functionTool(name: string, fn: Tool): void {
  // 함수를 도구 목록에 등록
  TOOLS[name] = fn;
}

functionTool("check_slot", (ctx, args) => ({ time: args.time, available: !ctx.userdata.booked.includes(args.time) })); // 희망 시각에 빈자리가 있는지 확인

interface Message {
  role: string;
  content: string;
}

interface LlmOut {
  toolCall?: { name: string; args: Record<string, string> };
  text?: string;
}

function fakeLlm(history: Message[]): LlmOut {
  // 도구 결과가 아직 없으면 도구를 요청하고, 결과가 있으면 말로 답한다
  const last = history[history.length - 1];
  if (last.role === "user") return { toolCall: { name: "check_slot", args: { time: "15:00" } } };
  const result = JSON.parse(last.content);
  return { text: result.available ? "네, 15시에 자리가 있어요." : "15시는 마감이에요." };
}

function turn(userText: string, ctx: RunContext): string[] {
  // 한 턴을 돌리며 사건 이름을 순서대로 모은다
  const history: Message[] = [{ role: "user", content: userText }];
  const events = ["user_message"];
  let out = fakeLlm(history);
  while (out.toolCall) {
    // 도구 요청이 오는 동안 반복
    const { name, args } = out.toolCall;
    events.push(`function_call ${name}(${JSON.stringify(args)})`);
    const result = TOOLS[name](ctx, args);
    events.push(`function_output ${JSON.stringify(result)}`);
    history.push({ role: "tool", content: JSON.stringify(result) });
    out = fakeLlm(history);
  }
  events.push(`assistant_message ${out.text}`);
  return events;
}

const events = turn("오늘 세 시에 예약할 수 있어요?", { userdata: { booked: ["10:00", "11:00"] } });
for (const e of events) console.log(" ", e);
check(events.map((e) => e.split(" ")[0]).join() === "user_message,function_call,function_output,assistant_message" && events[events.length - 1].includes("15시에 자리가"), "사건 순서는 user → function_call → function_output → assistant여야 해요.");

handoff.python:
# D30 · Part 1 · Handoff · 공유 메모: 예약 담당 → 수납 담당으로 통화 넘기기 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d30_handoff.py   (LiveKit Agents 없이 · 인터넷·GPU·마이크·API 키 불필요)
#   도구가 다른 Agent를 돌려주면 세션이 담당을 바꾼다. userdata(공유 메모)는 담당이 바뀌어도 이어지고, chat_ctx를 넘기면 앞 대화도 이어진다
#   (대체: livekit.agents의 Handoff 반환 대신 도구가 Agent 객체를 반환하는 미니 구현, LLM은 키워드 규칙)
from dataclasses import dataclass, field


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


@dataclass
class Agent:
    name: str
    chat_ctx: list[str] = field(default_factory=list)  # 앞 담당과 나눈 대화

    def handle(self, text: str, userdata: dict):
        """(답, 다음 담당 또는 None)을 돌려준다."""
        raise NotImplementedError


class Reservation(Agent):
    def handle(self, text, userdata):
        if "비용" in text or "얼마" in text:
            return "수납 담당에게 연결해 드릴게요.", Billing("billing", chat_ctx=self.chat_ctx)    # Handoff: 대화 기록을 함께 넘김
        userdata["slot"] = "15:00"
        return "내일 15시로 예약했어요.", None


class Billing(Agent):
    def handle(self, text, userdata):
        return f"{userdata['slot']} 예약 건의 비용은 5만 원입니다. (앞 대화 {len(self.chat_ctx) - 1}줄 이어받음)", None


class Session:
    def __init__(self, agent: Agent) -> None:
        self.agent, self.userdata, self.log = agent, {}, []

    def say(self, text: str) -> str:
        self.agent.chat_ctx.append(f"user: {text}")
        reply, nxt = self.agent.handle(text, self.userdata)
        self.agent.chat_ctx.append(f"assistant: {reply}")
        self.log.append(f"[{self.agent.name}] {reply}")
        if nxt is not None:
            self.agent = nxt                           # 담당 교체
        return reply


s = Session(Reservation("reservation"))
s.say("내일 세 시에 예약해 주세요")
s.say("비용은 얼마예요?")
s.say("그 예약 건 비용 알려 주세요")
for line in s.log:
    print(" ", line)
check(s.agent.name == "billing" and s.userdata == {"slot": "15:00"} and "15:00" in s.log[-1] and "4줄 이어받음" in s.log[-1],
      "수납 담당이 공유 메모의 예약 시각과 앞 대화 4줄을 이어받아야 해요.")

handoff.typescript:
// D30 · Part 1 · Handoff · 공유 메모: 예약 담당 → 수납 담당으로 통화 넘기기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_handoff.ts
//   도구가 다른 Agent를 돌려주면 세션이 담당을 바꾼다. userdata(공유 메모)는 담당이 바뀌어도 이어지고, chatCtx를 넘기면 앞 대화도 이어진다
//   (대체: @livekit/agents의 handoff 반환 대신 도구가 Agent 객체를 반환하는 미니 구현, LLM은 키워드 규칙)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type UserData = { slot?: string };

class Agent {
  name: string;
  chatCtx: string[]; // 앞 담당과 나눈 대화
  constructor(name: string, chatCtx: string[] = []) {
    this.name = name;
    this.chatCtx = chatCtx;
  }
  handle(_text: string, _userdata: UserData): [string, Agent | null] {
    throw new Error("구현 필요");
  }
}

class Billing extends Agent {
  handle(_text: string, userdata: UserData): [string, Agent | null] {
    return [`${userdata.slot} 예약 건의 비용은 5만 원입니다. (앞 대화 ${this.chatCtx.length - 1}줄 이어받음)`, null];
  }
}

class Reservation extends Agent {
  handle(text: string, userdata: UserData): [string, Agent | null] {
    if (text.includes("비용") || text.includes("얼마")) return ["수납 담당에게 연결해 드릴게요.", new Billing("billing", this.chatCtx)]; // Handoff: 대화 기록을 함께 넘김
    userdata.slot = "15:00";
    return ["내일 15시로 예약했어요.", null];
  }
}

class Session {
  agent: Agent;
  userdata: UserData = {};
  log: string[] = [];
  constructor(agent: Agent) {
    this.agent = agent;
  }
  say(text: string): string {
    this.agent.chatCtx.push(`user: ${text}`);
    const [reply, next] = this.agent.handle(text, this.userdata);
    this.agent.chatCtx.push(`assistant: ${reply}`);
    this.log.push(`[${this.agent.name}] ${reply}`);
    if (next) this.agent = next; // 담당 교체
    return reply;
  }
}

const s = new Session(new Reservation("reservation"));
s.say("내일 세 시에 예약해 주세요");
s.say("비용은 얼마예요?");
s.say("그 예약 건 비용 알려 주세요");
for (const line of s.log) console.log(" ", line);
check(s.agent.name === "billing" && JSON.stringify(s.userdata) === '{"slot":"15:00"}' && s.log[s.log.length - 1].includes("15:00") && s.log[s.log.length - 1].includes("4줄 이어받음"), "수납 담당이 공유 메모의 예약 시각과 앞 대화 4줄을 이어받아야 해요.");

sip.typescript:
// D30 · Part 2 · 전화가 들어오는 길: SIP Trunk · Dispatch Rule 요청서 만들기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_sip.ts   (요청서를 만들기만 하고 보내지 않아요)
//   전화번호 → Trunk(어느 번호·어느 통신사 IP를 받나) → Dispatch Rule(어느 방으로 넣나) → 방 이름이 정해지는 과정을 JSON으로 확인
//   (대체: livekit-server-sdk의 SIP 요청 객체 대신 같은 필드의 객체 · 번호와 IP는 문서용 예시값)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Trunk {
  trunk: { name: string; numbers: string[]; allowed_addresses: string[] };
}

interface Rule {
  trunk_names: string[];
  rule: { dispatch_rule_individual: { room_prefix: string } };
  attributes: Record<string, string>;
}

interface Call {
  to: string;
  from: string;
  fromIp: string;
}

function inboundTrunk(name: string, numbers: string[], allowedIps: string[]): Trunk {
  // 들어오는 전화를 받을 문: 이 번호로 오고 이 주소에서 온 전화만 통과
  return { trunk: { name, numbers, allowed_addresses: allowedIps } };
}

function dispatchRule(trunkName: string, prefix: string): Rule {
  // 통화마다 방을 따로 만드는 규칙 (individual): 방 이름 = prefix + 발신번호
  return { trunk_names: [trunkName], rule: { dispatch_rule_individual: { room_prefix: prefix } }, attributes: { source: "phone" } };
}

function route(call: Call, trunk: Trunk, rule: Rule): string | null {
  // 전화 한 통이 어느 방으로 가는지. 번호나 주소가 안 맞으면 거절(null)
  const t = trunk.trunk;
  if (!t.numbers.includes(call.to) || !t.allowed_addresses.includes(call.fromIp)) return null;
  return rule.rule.dispatch_rule_individual.room_prefix + call.from;
}

const trunk = inboundTrunk("hanbit-in", ["+827012345678"], ["203.0.113.10"]);
const rule = dispatchRule("hanbit-in", "call-");
console.log(JSON.stringify({ trunk, rule }, null, 1).slice(0, 300), "...");
const ok = route({ to: "+827012345678", from: "+821011112222", fromIp: "203.0.113.10" }, trunk, rule);
const wrongNumber = route({ to: "+827099999999", from: "+821011112222", fromIp: "203.0.113.10" }, trunk, rule);
const wrongIp = route({ to: "+827012345678", from: "+821011112222", fromIp: "198.51.100.7" }, trunk, rule);
console.log("정상 전화 →", ok, "· 다른 번호 →", wrongNumber, "· 모르는 주소 →", wrongIp);
check(ok === "call-+821011112222" && wrongNumber === null && wrongIp === null, "번호와 주소가 맞는 전화만 call-발신번호 방으로 들어가야 해요.");

dispatch.typescript:
// D30 · Part 2~4 · 전화 한 통의 일생: 벨 → 방 생성 → 비서 출근 → 통화 → 종료 상태 기계 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_dispatch.ts
//   통화는 정해진 순서로만 상태가 바뀐다. 건너뛰거나 되돌리면 거절하고, 통화 기록(call log)을 남긴다
//   (대체: 실제 SIP 신호와 Job 대신 상태 이름과 허용 전이 표)
const ALLOWED: Record<string, string[]> = {
  ringing: ["room_created", "rejected"],
  room_created: ["agent_dispatched"],
  agent_dispatched: ["connected"],
  connected: ["hangup"],
  hangup: ["job_done"],
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class Call {
  number: string;
  state = "ringing";
  log: string[] = ["ringing"];
  constructor(number: string) {
    this.number = number;
  }
  go(next: string): boolean {
    // 허용된 다음 상태로만 넘어간다. 아니면 false(거절)
    if (!(ALLOWED[this.state] ?? []).includes(next)) return false;
    this.state = next;
    this.log.push(next);
    return true;
  }
}

const c = new Call("+821011112222");
const skipped = c.go("connected"); // 벨 → 바로 통화 (건너뛰기) → 거절
const steps = ["room_created", "agent_dispatched", "connected", "hangup", "job_done"];
const done = steps.map((s) => c.go(s));
const back = c.go("connected"); // 끝난 통화를 되살리기 → 거절
console.log("통화 기록:", c.log.join(" → "));
check(!skipped && done.every(Boolean) && !back && c.log.join() === ["ringing", ...steps].join(), "순서를 건너뛰거나 되돌리면 거절하고, 정상 흐름만 기록돼야 해요.");

phone.typescript:
// D30 · Part 2 · 전화 음질: 300~3,400 Hz만 남기고 8 kHz로 줄이면 무엇이 사라지나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_phone.ts   (소리는 코드 안에서 합성해요)
//   16 kHz 합성음(200 · 1000 · 3000 · 5000 Hz)을 FFT로 전화 대역(300~3,400 Hz)만 통과시키고 2칸씩 건너뛰어 8 kHz로 만든다
//   (대체: 실제 전화 코덱(G.711) 대신 주파수 마스크 + 간격 줄이기)
const SR = 16000;
const N = 4096;
const BIN = SR / N; // FFT 한 칸 = 3.90625 Hz

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 radix-2 FFT (길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = i + k + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function phoneFilter(y: Float64Array, lo: number = 300, hi: number = 3400): Float64Array {
  // 주파수 영역에서 lo~hi Hz만 남긴다 (대역 통과). 음수 주파수 쪽도 대칭으로 지운다
  const re = Float64Array.from(y);
  const im = new Float64Array(y.length);
  fft(re, im);
  for (let k = 0; k < y.length; k++) {
    const f = Math.min(k, y.length - k) * BIN;
    if (f < lo || f > hi) {
      re[k] = 0;
      im[k] = 0;
    }
  }
  for (let k = 0; k < y.length; k++) im[k] = -im[k]; // 켤레를 취해 같은 FFT로 역변환
  fft(re, im);
  return re.map((v) => v / y.length);
}

function amp(y: Float64Array, k: number): number {
  const re = Float64Array.from(y);
  const im = new Float64Array(y.length);
  fft(re, im);
  return Math.hypot(re[k], im[k]) / (y.length / 2);
}

const ks: Record<string, number> = { "200Hz": 51, "1000Hz": 256, "3000Hz": 768, "5000Hz": 1280 }; // 정확히 FFT 칸에 맞춘 톤
const y = new Float64Array(N).map((_, i) => Object.values(ks).reduce((s, k) => s + 0.2 * Math.sin((2 * Math.PI * k * BIN * i) / SR), 0));
const out = phoneFilter(y);
const phone = out.filter((_, i) => i % 2 === 0); // 16 kHz → 8 kHz (통과 대역이 4 kHz 아래라 겹침 없음)
const kept: Record<string, number> = {};
for (const [name, k] of Object.entries(ks)) {
  kept[name] = amp(out, k) / amp(y, k);
  console.log(`${name.padStart(7)}: ${(kept[name] * 100).toFixed(0).padStart(3)}% 남음`);
}
console.log(`샘플 수 ${y.length} → ${phone.length} (8 kHz)`);
check(kept["200Hz"] < 0.01 && kept["5000Hz"] < 0.01 && kept["1000Hz"] > 0.99 && kept["3000Hz"] > 0.99 && phone.length === N / 2, "200 Hz와 5 kHz는 사라지고 1 kHz · 3 kHz는 남아야 해요.");

s2s.python:
# D30 · Part 3 · Cascade vs S2S: 귀 · 머리 · 입을 따로 쓸 때와 한 모델로 합칠 때 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d30_s2s.py   (OpenAI Realtime · Gemini Live 없이 · 인터넷·GPU·마이크·API 키 불필요)
#   Cascade(VAD → STT → LLM → TTS)는 단계마다 지연이 쌓이고, S2S는 오디오가 모델에 바로 들어가 오디오로 나온다
#   (대체: 실제 모델 호출 대신 단계별 가정 지연(초)을 더한 비교 · 숫자는 예시)
CASCADE = [("턴 끝 판단", 0.5), ("STT", 0.3), ("LLM 첫 글자", 0.4), ("TTS 첫 소리", 0.2)]
S2S = [("서버 VAD 턴 끝", 0.3), ("S2S 모델 첫 소리", 0.35)]


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


class FakeRealtimeModel:
    """S2S 모델 흉내: 오디오 조각을 받아 오디오 조각을 돌려준다. 중간 글자는 선택 사항(전사)."""

    def respond(self, audio: bytes) -> dict:
        return {"audio": b"\x00" * len(audio), "transcript": "네, 예약 도와드릴게요."}


def total(stages: list[tuple[str, float]]) -> float:
    return round(sum(s for _, s in stages), 2)


for name, stages in (("Cascade", CASCADE), ("S2S", S2S)):
    print(f"{name:<8} {len(stages)}단계: " + " + ".join(f"{n} {s}" for n, s in stages) + f" = {total(stages)}초")
out = FakeRealtimeModel().respond(b"\x01" * 640)
check(total(CASCADE) == 1.4 and total(S2S) == 0.65 and len(S2S) < len(CASCADE) and len(out["audio"]) == 640 and out["transcript"].startswith("네"),
      "S2S는 단계가 적어 더 빠르고, 오디오가 오디오로 바로 나와야 해요.")

s2s.typescript:
// D30 · Part 3 · Cascade vs S2S: 귀 · 머리 · 입을 따로 쓸 때와 한 모델로 합칠 때 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_s2s.ts
//   Cascade(VAD → STT → LLM → TTS)는 단계마다 지연이 쌓이고, S2S는 오디오가 모델에 바로 들어가 오디오로 나온다
//   (대체: 실제 모델 호출 대신 단계별 가정 지연(초)을 더한 비교 · 숫자는 예시)
type Stage = [string, number];
const CASCADE: Stage[] = [["턴 끝 판단", 0.5], ["STT", 0.3], ["LLM 첫 글자", 0.4], ["TTS 첫 소리", 0.2]];
const S2S: Stage[] = [["서버 VAD 턴 끝", 0.3], ["S2S 모델 첫 소리", 0.35]];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function fakeRealtimeRespond(audio: Buffer): { audio: Buffer; transcript: string } {
  // S2S 모델 흉내: 오디오 조각을 받아 오디오 조각을 돌려준다. 중간 글자는 선택 사항(전사)
  return { audio: Buffer.alloc(audio.length), transcript: "네, 예약 도와드릴게요." };
}

const total = (stages: Stage[]): number => Math.round(stages.reduce((s, [, v]) => s + v, 0) * 100) / 100;

for (const [name, stages] of [["Cascade", CASCADE], ["S2S", S2S]] as [string, Stage[]][]) {
  console.log(`${name.padEnd(8)} ${stages.length}단계: ${stages.map(([n, s]) => `${n} ${s}`).join(" + ")} = ${total(stages)}초`);
}
const out = fakeRealtimeRespond(Buffer.alloc(640, 1));
check(total(CASCADE) === 1.4 && total(S2S) === 0.65 && S2S.length < CASCADE.length && out.audio.length === 640 && out.transcript.startsWith("네"), "S2S는 단계가 적어 더 빠르고, 오디오가 오디오로 바로 나와야 해요.");

caps.typescript:
// D30 · Part 3 · 능력 표 읽기: 요구 사항으로 Cascade와 S2S 중 고르기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_caps.ts
//   능력 표(○ 쉬움 · △ 가능하지만 번거로움 · × 어려움)에 가중치를 곱해 점수를 내고, 한빛치과 전화 상담에는 무엇이 맞는지 본다
//   (대체: 노트북의 능력 표 대신 같은 취지의 예시 점수)
const SCORE: Record<string, number> = { "○": 2, "△": 1, "×": 0 };
const CAPS: Record<string, [string, string]> = {
  // 능력: [Cascade, S2S]
  "도구 호출 정확도·로그": ["○", "△"],
  "STT·LLM·TTS 부분 교체": ["○", "×"],
  "첫 소리까지 빠르기": ["△", "○"],
  "억양·감정 자연스러움": ["△", "○"],
  "통화 내용 글자 기록(규정)": ["○", "△"],
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function pick(weights: Record<string, number>): [string, number, number] {
  // 능력별 가중치(중요도 0~3)로 점수를 합쳐 더 높은 쪽을 고른다
  let c = 0;
  let s = 0;
  for (const [k, w] of Object.entries(weights)) {
    c += SCORE[CAPS[k][0]] * w;
    s += SCORE[CAPS[k][1]] * w;
  }
  return [c >= s ? "Cascade" : "S2S", c, s];
}

const clinic = { "도구 호출 정확도·로그": 3, "통화 내용 글자 기록(규정)": 3, "STT·LLM·TTS 부분 교체": 2, "첫 소리까지 빠르기": 1 }; // 병원: 예약 도구 · 기록 · 부품 교체가 중요
const chatDemo = { "억양·감정 자연스러움": 3, "첫 소리까지 빠르기": 3 }; // 잡담 데모: 자연스러움과 속도
const a = pick(clinic);
const b = pick(chatDemo);
console.log("한빛치과 전화 상담:", JSON.stringify(a), "· 잡담 데모:", JSON.stringify(b));
check(a[0] === "Cascade" && b[0] === "S2S", "도구·기록이 중요하면 Cascade, 자연스러움·속도가 중요하면 S2S가 나와야 해요.");

recap.typescript:
// D30 · Part 5 · 정리 퀴즈: 도구 · Handoff · SIP · 전화 음질 · S2S 다섯 가지를 숫자로 확인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d30_recap.ts
//   (대체: 개념 퀴즈의 답을 코드로 계산)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 도구를 n번 쓰는 턴의 사건 수: 사용자 1 + (call + output) x n + 답 1
const toolLoopEvents = (nTools: number): number => 1 + 2 * nTools + 1;
const roomName = (prefix: string, caller: string): string => prefix + caller;
const phoneSamples = (ms: number): number => Math.floor((8000 * ms) / 1000);

const quiz: Record<string, string | number> = {
  "도구 2번 쓰는 턴의 사건 수": toolLoopEvents(2),
  "Handoff 뒤에도 이어지는 공유 메모 이름": "userdata",
  "전화 방 이름(call- + 발신번호)": roomName("call-", "+821011112222"),
  "전화 20 ms 조각 샘플 수": phoneSamples(20),
  "S2S가 Cascade보다 줄이는 것": "STT·LLM·TTS 사이의 단계 지연",
};
for (const [q, a] of Object.entries(quiz)) console.log(`${q}: ${a}`);
check(quiz["도구 2번 쓰는 턴의 사건 수"] === 6 && quiz["전화 방 이름(call- + 발신번호)"] === "call-+821011112222" && quiz["전화 20 ms 조각 샘플 수"] === 160, "도구 2번이면 사건 6개, 전화 20 ms는 160샘플이에요.");
